let mode='menu',level=1,score=0,lives=3,elapsed=0,clock=180,spawnTimer=1.8,barrels=[],sparks=[],popups=[],coins=[],hammer=null,hammerTime=0,shake=0,invincible=0,accumulator=0,lastTime=0,visualTime=0,justJump=false,throwAnim=0,toastTime=0;
