function ground(i,x){return 750-i*101+(x-270)*(i%2===0?-.032:.032);}
function ladderList(){const xs=level===2?[428,110,390,142,420]:level===3?[458,120,430,100,370]:[455,88,440,104,402];return xs.map((x,i)=>({x,bottom:i,top:i+1,y1:ground(i+1,x),y2:ground(i,x)}));}
