function updateHUD(){ $('score').textContent=String(score).padStart(6,'0');$('best').textContent=String(Math.max(best,score)).padStart(6,'0');$('level').textContent=String(level).padStart(2,'0');$('lives').textContent='♥ '.repeat(lives).trim()+' ♡'.repeat(3-lives);$('sound').classList.toggle('off',!soundOn);$('sound').textContent=soundOn?'♪':'♪̸';$('sound').setAttribute('aria-pressed',String(soundOn));}
