function toast(text){$('toast').textContent=text;$('toast').style.opacity=1;toastTime=3;}
function resetInput(){keys.clear();touch.clear();justJump=false;document.querySelectorAll('[data-key]').forEach(b=>b.classList.remove('pressed'));}
