function clearLevel(){mode=level===3?'victory':'stageclear';score+=Math.floor(clock)*10;lives=Math.min(3,lives+1);saveBest();audio.effect('win');audio.pause();showOverlay(mode);$('status').textContent='TOWER SECURED';for(let i=0;i<70;i++)sparks.push({x:270,y:330,vx:(Math.random()-.5)*400,vy:-Math.random()*300,life:3,color:['#cfee90','#faac6d','#80c6ce'][i%3]});}
function hit(){if(invincible>0||mode!=='playing')return;lives--;shake=.35;audio.effect('hit');burst(player.x,player.y-18,22,'#ffae79');hammerTime=0;if(lives<=0){mode='gameover';saveBest();audio.pause();showOverlay('gameover');$('status').textContent='TRY AGAIN';}else{const f=player.floor;const x=f===0?65:ladders[f-1].x;Object.assign(player,{x,y:ground(f,x),vy:0,onGround:true,climbing:null});barrels=[];spawnTimer=2;invincible=2.6;toast('小心滾桶！還有 '+lives+' 次機會');updateHUD();}}
function burst(x,y,count,color){for(let i=0;i<count;i++)sparks.push({x,y,vx:(Math.random()-.5)*180,vy:-Math.random()*190,life:.5+Math.random()*.4,color});}
