function update(dt){visualTime+=dt;if(toastTime>0){toastTime-=dt;if(toastTime<=0)$('toast').style.opacity=0;}for(const a of sparks){a.x+=a.vx*dt;a.y+=a.vy*dt;a.vy+=400*dt;a.life-=dt;}sparks=sparks.filter(a=>a.life>0);for(const p of popups){p.y-=35*dt;p.life-=dt;}popups=popups.filter(p=>p.life>0);if(mode!=='playing')return;
elapsed+=dt;clock=Math.max(0,180-elapsed);const timer=$('timer');if(timer)timer.textContent=Math.ceil(clock)+'s';if(clock<=0){hit();elapsed=0;clock=180;return;}invincible=Math.max(0,invincible-dt);shake=Math.max(0,shake-dt);hammerTime=Math.max(0,hammerTime-dt);throwAnim=Math.max(0,throwAnim-dt);
const left=keys.has('ArrowLeft')||keys.has('KeyA'),right=keys.has('ArrowRight')||keys.has('KeyD'),up=keys.has('ArrowUp')||keys.has('KeyW'),down=keys.has('ArrowDown')||keys.has('KeyS');
if(!player.climbing&&player.onGround&&(up||down)){const l=ladders.find(l=>Math.abs(l.x-player.x)<19&&((up&&l.bottom===player.floor)||(down&&l.top===player.floor)));if(l){player.climbing=l;player.x=l.x;player.onGround=false;player.vy=0;}}
if(player.climbing){const l=player.climbing;const dy=(down?1:0)-(up?1:0);player.y+=dy*119*dt;player.walk+=dy*dt*11;if(player.y<=l.y1){player.y=l.y1;player.floor=l.top;player.climbing=null;player.onGround=true;audio.effect('step');}else if(player.y>=l.y2){player.y=l.y2;player.floor=l.bottom;player.climbing=null;player.onGround=true;}}
else{player.vx=((right?1:0)-(left?1:0))*153;if(player.vx){player.facing=Math.sign(player.vx);player.walk+=dt*12;}player.x=Math.min(496,Math.max(43,player.x+player.vx*dt));if(justJump&&player.onGround){player.vy=-342;player.onGround=false;audio.effect('jump');}if(!player.onGround){player.vy+=990*dt;player.y+=player.vy*dt;if(player.vy>=0&&player.y>=ground(player.floor,player.x)){player.y=ground(player.floor,player.x);player.vy=0;player.onGround=true;}}else player.y=ground(player.floor,player.x);}
justJump=false;
spawnTimer-=dt;if(spawnTimer<=0){spawnBarrel();spawnTimer=Math.max(1.5,3.5-level*.42)+(Math.sin(elapsed*2)+1)*.2;}
for(const b of barrels){b.angle+=b.dir*b.speed*dt/12;if(!b.fall){b.x+=b.dir*b.speed*dt;b.y=ground(b.floor,b.x)-12;if((b.dir===1&&b.x>=509)||(b.dir===-1&&b.x<=31)){b.fall=true;b.vy=15;}}
else{b.vy+=500*dt;b.y+=b.vy*dt;if(b.floor>0&&b.y+12>=ground(b.floor-1,b.x)){b.floor--;b.dir*=-1;b.fall=false;b.passed=false;b.vy=0;}else if(b.floor===0&&b.y>790)b.dead=true;}
const dx=Math.abs(b.x-player.x),dy=Math.abs(b.y-(player.y-15));if(dx<42&&dy<54&&hammerTime>0){b.dead=true;points(b.x,b.y,200);burst(b.x,b.y,12,'#e5fba6');audio.effect('smash');}else if(dx<19&&dy<24){hit();break;}else if(!b.passed&&!b.fall&&player.floor===b.floor&&dx<20&&!player.onGround&&!player.climbing&&player.y<b.y-18){b.passed=true;points(player.x,player.y-40,100);audio.effect('coin');}}
barrels=barrels.filter(b=>!b.dead);
coins=coins.filter(c=>{if(player.floor===c.floor&&Math.abs(player.x-c.x)<23&&Math.abs(player.y-ground(c.floor,c.x))<35){points(c.x,ground(c.floor,c.x)-40,300);audio.effect('coin');burst(c.x,ground(c.floor,c.x)-24,12,'#e7f8a4');return false;}return true;});
if(hammer&&player.floor===hammer.floor&&Math.abs(player.x-hammer.x)<24&&Math.abs(player.y-ground(hammer.floor,hammer.x))<35){hammer=null;hammerTime=8;audio.effect('power');toast('獲得動力鎚！8 秒內擊碎滾桶');}
if(player.floor===5&&player.x>450&&player.onGround)clearLevel();
}
