const audio={ctx:null,gain:null,next:0,step:0,active:false,init(){if(this.ctx)return;const AC=window.AudioContext||window.webkitAudioContext;if(!AC)return;try{this.ctx=new AC();this.gain=this.ctx.createGain();this.gain.gain.value=soundOn?.26:0;this.gain.connect(this.ctx.destination);}catch{}},tone(freq,start,len,type='square',vol=.08,end){if(!this.ctx||!soundOn)return;const o=this.ctx.createOscillator(),g=this.ctx.createGain();o.type=type;o.frequency.setValueAtTime(freq,start);if(end)o.frequency.exponentialRampToValueAtTime(end,start+len);g.gain.setValueAtTime(0,start);g.gain.linearRampToValueAtTime(vol,start+.006);g.gain.exponentialRampToValueAtTime(.0001,start+len);o.connect(g);g.connect(this.gain);o.start(start);o.stop(start+len+.01);},resume(){this.init();if(!this.ctx)return;this.ctx.resume().catch(()=>{});this.active=true;this.next=this.ctx.currentTime+.05;},pause(){this.active=false;},tick(){if(!this.ctx||!this.active||!soundOn)return;let n=0;while(this.next<this.ctx.currentTime+.12&&n++<8){const seq=[76,0,79,83,81,79,76,74,72,0,76,79,78,74,71,74,76,0,79,83,86,83,81,79,78,74,71,74,76,0,0,0],m=seq[this.step%32],t=this.next;if(m)this.tone(440*2**((m-69)/12),t,.13,'square',.057);if(this.step%2===0){const bass=[40,40,43,43,45,45,47,47][Math.floor(this.step/4)%8];this.tone(440*2**((bass-69)/12),t,.2,'triangle',.17);}if(this.step%4===0)this.tone(100,t,.075,'sine',.2,35);else if(this.step%4===2)this.tone(170,t,.045,'triangle',.045,50);this.step++;this.next+=.145;}if(this.next<this.ctx.currentTime)this.next=this.ctx.currentTime+.03;},effect(kind){if(!this.ctx||!soundOn)return;const t=this.ctx.currentTime;const sets={jump:[[220,0,.11,'square',.1,650]],coin:[[880,0,.08],[1320,.08,.17]],hit:[[180,0,.3,'sawtooth',.13,40]],roll:[[75,0,.07,'triangle',.09,42]],step:[[390,0,.055,'triangle',.055]],power:[[440,0,.1],[660,.1,.1],[880,.2,.2]],smash:[[110,0,.13,'sawtooth',.1,30]],win:[[523,0,.13],[659,.13,.13],[784,.26,.13],[1047,.39,.45]]};for(const a of sets[kind]||[])this.tone(a[0],t+a[1],a[2],a[3]||'square',a[4]||.09,a[5]);},toggle(){soundOn=!soundOn;this.init();if(this.ctx){this.ctx.resume().catch(()=>{});this.gain.gain.value=soundOn?.26:0;this.next=this.ctx.currentTime+.03;}try{localStorage.setItem('barrelbound.sound.v1',soundOn?'on':'off');}catch{}updateHUD();}};
